<template><ion-page><ion-content class="auth-bg"><main class="auth-card"><p class="eyebrow">NOVA SENHA</p><h1>Escolha uma senha nova.</h1><form @submit.prevent="submit"><label>Nova senha</label><ion-input v-model="password" type="password" autocomplete="new-password" required /><label>Confirme a senha</label><ion-input v-model="confirm" type="password" autocomplete="new-password" required /><p v-if="notice.message" class="notice" :class="notice.kind">{{notice.message}}</p><ion-button expand="block" type="submit" :disabled="busy">{{busy?'Salvando...':'Salvar nova senha'}}</ion-button></form></main></ion-content></ion-page></template>
<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{IonPage,IonContent,IonInput,IonButton}from'@ionic/vue';import{updatePassword}from'../services/auth';import{useNotice}from'../composables/useNotice';const router=useRouter(),password=ref(''),confirm=ref(''),busy=ref(false),notice=useNotice();async function submit(){if(password.value.length<6){notice.show('A senha precisa ter pelo menos 6 caracteres.');return}if(password.value!==confirm.value){notice.show('As senhas não conferem.');return}busy.value=true;try{const{error}=await updatePassword(password.value);if(error)throw error;notice.show('Senha atualizada com sucesso.','success');setTimeout(()=>router.replace('/boas-vindas'),1000)}catch(e){notice.show(e instanceof Error?e.message:'O link pode ter expirado. Solicite uma nova recuperação.')}finally{busy.value=false}}</script>
